parameters.jsCode:
const input = $json;

// n8n Form Trigger normally returns submitted fields directly.
// This also supports a nested body if the input shape changes later.
const data =
  input.body &&
  typeof input.body === 'object'
    ? input.body
    : input;

const requesterNameRaw =
  data['Requester Name'] ??
  data.requester_name ??
  data.requesterName ??
  '';

const requesterIdRaw =
  data['Requester ID'] ??
  data.requester_id ??
  data.requesterId ??
  '';

const questionRaw =
  data['Report Question'] ??
  data.report_question ??
  data.question ??
  '';

const requesterName =
  typeof requesterNameRaw === 'string'
    ? requesterNameRaw.trim()
    : '';

const requesterId =
  typeof requesterIdRaw === 'string' &&
  requesterIdRaw.trim()
    ? requesterIdRaw.trim()
    : 'form_requester_001';

const question =
  typeof questionRaw === 'string'
    ? questionRaw.trim()
    : '';

const receivedAt =
  typeof input.submittedAt === 'string' &&
  input.submittedAt.trim()
    ? input.submittedAt
    : new Date().toISOString();

return {
  channel: 'form',

  requester_id: requesterId,

  requester_name:
    requesterName || 'Form Requester',

  question,

  source: 'form_submission',

  received_at: receivedAt,

  environment: 'development',

  status: 'received'
};

parameters.responseText:
